pattern.usage:

import { InlineCitation } from '@/app/components/Bibliography/InlineCitation';

// Uso simples
<p>
  A incidência é de 50/100.000 habitantes
  <InlineCitation citation="[1]" references={references} />
</p>

// Múltiplas citações
<p>
  Estudos demonstram eficácia
  <InlineCitation citation="[1,2,3]" references={references} />
</p>

// Com tooltip automático
// O componente mostra tooltip com referência completa no hover

pattern.algorithm:

1. Identificar todas claims usando regex_patterns
2. Para cada claim, verificar se seguida de [n]
3. Se não seguida de citação, marcar como gap
4. Gerar relatório de gaps com contexto

// Pseudo-código
function detectGaps(text: string): Gap[] {
  const claims = findClaims(text, patterns);
  return claims.filter(claim => {
    const afterClaim = text.slice(claim.end, claim.end + 10);
    return !afterClaim.match(/\[\d+/);
  });
}

pattern.query_construction:

// Construir query baseada no contexto da claim
function buildPubMedQuery(claim: Claim): string {
  const terms = extractKeyTerms(claim.text);
  const filters = [
    "Systematic Review[pt]",
    "Meta-Analysis[pt]",
    "Guideline[pt]"
  ];

  // Limitar aos últimos 5 anos
  const dateFilter = `("${currentYear - 5}"[Date - Publication] : "3000"[Date - Publication])`;

  return `(${terms.join(' AND ')}) AND (${filters.join(' OR ')}) AND ${dateFilter}`;
}

// Exemplo de query gerada
// (breast cancer screening) AND (Systematic Review[pt] OR Meta-Analysis[pt]) AND ("2020"[Date - Publication] : "3000"[Date - Publication])

pattern.workflow:

async function validateDOI(doi: string): Promise<ValidationResult> {
  const url = `https://api.crossref.org/works/${encodeURIComponent(doi)}`;

  try {
    const response = await fetch(url);
    if (response.status === 200) {
      const data = await response.json();
      return {
        valid: true,
        metadata: {
          title: data.message.title[0],
          authors: data.message.author,
          journal: data.message['container-title'][0],
          year: data.message.published['date-parts'][0][0],
          volume: data.message.volume,
          page: data.message.page
        }
      };
    }
    return { valid: false, error: 'DOI not found' };
  } catch (e) {
    return { valid: false, error: e.message };
  }
}

pattern.formatter:

function formatVancouver(ref: Citation): string {
  if (ref.tipo === 'artigo') {
    const authors = ref.autores;
    const title = ref.titulo;
    const journal = ref.revista;
    const year = ref.ano;
    const volume = ref.volume ? `;${ref.volume}` : '';
    const issue = ref.numero ? `(${ref.numero})` : '';
    const pages = ref.paginas ? `:${ref.paginas}` : '';
    const doi = ref.doi ? ` doi:${ref.doi}` : '';

    return `${authors}. ${title}. ${journal}. ${year}${volume}${issue}${pages}.${doi}`;
  }

  if (ref.tipo === 'guideline') {
    return `${ref.autores}. ${ref.titulo}. ${ref.ano}.`;
  }

  if (ref.tipo === 'website') {
    return `${ref.autores}. ${ref.titulo} [Internet]. ${ref.ano} [cited ${ref.acessado}]. Available from: ${ref.url}`;
  }
}
